    push {lr}                                @ 08057270 00b5
    ldrb r1,[r0,#0x2]                        @ 08057272 8178
    lsls r2,r1,#0x1f    @ 08057274 ca07
    lsrs r2,r2,#0x1f    @ 08057276 d20f
